return items.map(item => {
  const o = item.json;
  const viral = Number(o.potencial_viral || 0);
  const negocio = Number(o.potencial_negocio || 0);
  const curiosidade = viral >= 85 ? 10 : viral >= 75 ? 7 : 5;
  const compartilhamento = viral >= 80 ? 10 : 7;
  const retencao = viral >= 80 ? 10 : 7;
  const score = Math.round((viral * 0.55) + (curiosidade * 2) + (compartilhamento * 2) + (retencao * 2));
  return {
    json: {
      ...o,
      viral_score: Math.min(100, score),
      etapa: 'VIRAL SCORE'
    }
  };
});

return items.map(item => {
  const o = item.json;
  const viral = Number(o.viral_score || 0);
  const negocio = Number(o.potencial_negocio || 0);
  const finalScore = Math.round((viral * 0.65) + (negocio * 0.35));
  return {
    json: {
      ...o,
      business_score: negocio,
      final_score: finalScore,
      prioridade: finalScore >= 85 ? 'ALTA' : finalScore >= 70 ? 'MEDIA' : 'BAIXA',
      etapa: 'BUSINESS SCORE'
    }
  };
});

const ordenados = [...items].sort((a, b) => Number(b.json.final_score || 0) - Number(a.json.final_score || 0));
const selecionado = ordenados[0];

return [{
  json: {
    ...selecionado.json,
    fact_check_status: 'PENDENTE_DE_FONTE',
    aprovado_para_publicacao: false,
    checklist_fact_check: [
      'Confirmar os fatos principais em fontes confiáveis.',
      'Confirmar datas, números e nomes.',
      'Separar fatos de opiniões.',
      'Não publicar enquanto não houver fonte suficiente.'
    ],
    observacao: 'MVP R$0: nenhuma fonte externa está conectada neste estágio.',
    etapa: 'FACT-CHECK'
  }
}];

return items.map(item => {
  const o = item.json;
  const roteiro = [
    `HOOK: ${o.hook}`,
    `CONTEXTO: ${o.relevancia}`,
    `DESENVOLVIMENTO: ${o.angulo}`,
    `VALOR: Explique o ponto principal de maneira simples e objetiva.`,
    `CTA: Se isso foi útil, salve e compartilhe.`
  ].join('\n\n');

  return {
    json: {
      ...o,
      roteiro,
      formato: 'Vídeo curto vertical',
      duracao_alvo: '25-45 segundos',
      etapa: 'ROTEIRISTA'
    }
  };
});

return items.map(item => {
  const o = item.json;
  const direcao = {
    abertura: 'Começar com texto grande na tela e corte rápido.',
    cena_1: 'Apresentar visualmente o problema ou curiosidade.',
    cena_2: 'Mostrar a explicação principal com elementos visuais simples.',
    cena_3: 'Destacar a conclusão ou solução.',
    edicao: 'Cortes rápidos, legendas, zooms discretos e mudança visual a cada poucos segundos.',
    audio: 'Narração clara e música de fundo discreta.'
  };

  return {
    json: {
      ...o,
      direcao,
      etapa: 'DIRETOR'
    }
  };
});

return items.map(item => {
  const o = item.json;
  const aprovado = o.aprovado_para_publicacao === true;
  const roteiro_ok = typeof o.roteiro === 'string' && o.roteiro.length > 50;
  const diretor_ok = !!o.direcao;
  const passou = aprovado && roteiro_ok && diretor_ok;

  return {
    json: {
      ...o,
      qa_status: passou ? 'APROVADO' : 'BLOQUEADO',
      qa_motivos: passou ? [] : [
        !aprovado ? 'Fact-check ainda não aprovado.' : null,
        !roteiro_ok ? 'Roteiro incompleto.' : null,
        !diretor_ok ? 'Direção visual incompleta.' : null
      ].filter(Boolean),
      etapa: 'QA'
    }
  };
});

return items.map(item => {
  const o = item.json;
  return {
    json: {
      ...o,
      growth: {
        objetivo: 'Testar conteúdo, medir resultado e alimentar o próximo ciclo.',
        plataformas: ['TikTok', 'Instagram Reels', 'YouTube Shorts'],
        metricas: ['retenção', 'visualizações', 'compartilhamentos', 'salvamentos', 'comentários', 'conversão'],
        testes: ['Hook A', 'Hook B', 'CTA A'],
        regra_mvp: 'Após os primeiros 10 conteúdos, comparar resultados e ajustar os pesos do cérebro.'
      },
      etapa: 'GROWTH'
    }
  };
});
